import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {Simulation} from '../shared/simulation.js';import {contractType} from '../shared/config.js';
const dir='evidence/audit-20261026',out={created:new Date().toISOString(),checks:[],observations:[]};
const advance=(s,n)=>{const end=s.time+n;while(s.time<end-1e-8)s.tick(Math.min(.05,end-s.time));};
function arena(id){const s=new Simulation();s.units=[];s.player.retired=true;s.waveAt=1e9;for(const t of s.towers)t.x=100;const make=(id,x,y)=>{const p=s.makePlayer(id===3?1:0,false);p.classId=id;p.level=6;p.builds[id]=[1,1,1,1];const h=s.spawn(p.side,contractType(id),0,1,x);s.contract(p,h.id);Object.assign(h,{x,y,cd:1e9,speed:0});return {p,h};};const {p,h}=make(id,0,0),{h:e}=make(id===3?0:3,0,3),{h:a}=make(id===3?3:0,1,0);e.maxHp=e.hp=1e7;e.targetId=a.id;a.hp=a.maxHp*.5;s.localPlayerId=p.id;return {s,p,h,e,a,make};}
function check(name,fn){try{out.checks.push({name,status:'PASS',evidence:fn()});}catch(e){out.checks.push({name,status:'FAIL',error:e.message,stack:e.stack});}}
for(const id of [0,2,3,4,5])for(let skill=0;skill<4;skill++)check(`class${id} skill${skill+1} death cancels pending windup and double tap only costs once`,()=>{const {s,p,h,e,a}=arena(id);if(id===5&&skill===2)s.debuff(a,e,'vulnerable',.2,10);const before=p.stamina;assert.ok(s.cast(skill),s.notice);assert.equal(s.cast(skill),false);assert.equal(p.stamina,before-s.config.heroes[id].skills[skill].cost);const hp=e.hp;s.damage(null,h,1e9);advance(s,1.5);assert.equal(e.hp,hp);assert.equal(s.fields.filter(f=>f.owner.id===h.id).length,0);return {cost:before-p.stamina};});
for(const [id,skill] of [[0,0],[0,2],[2,0],[2,1],[2,2],[2,3],[3,0],[3,1],[4,0],[4,1],[4,2],[4,3],[5,0]])check(`class${id} skill${skill+1} range inclusive then outside no-target rejection`,()=>{const {s,p,h,e,a}=arena(id),range=s.config.heroes[id].skills[skill].targetRange;e.y=range;assert.ok(s.castPlan(skill).ok);e.y=range+.001;assert.equal(s.castPlan(skill).ok,false);return {range};});
check('rune slow keeps promised 4s after last hit',()=>{const {s,h,e}=arena(2);s.cast(2);const timeline=[];for(const at of [.4,1.11,1.86,2.61,3.36,4,6,7.4]){advance(s,at-s.time);timeline.push({time:s.time,hpLost:1e7-e.hp,slow:s.activeDebuffs(e,'moveSlow').map(v=>({stacks:v.stacks,ratio:v.ratio,until:v.until})),stored:e.debuffs?.[h.id+':moveSlow'],spent:s.skillValues[0].spent,limit:s.skillValues[0].limit});}out.observations.push({name:'rune-slow-timeline',timeline});const row=timeline.find(x=>x.time>3.35&&x.time<3.4);assert.equal(row.slow.length,1,JSON.stringify(row));return timeline;});
check('hostile mark can be cleansed and blocked by lord immunity (negative-effect policy assumption)',()=>{const {s,h,e}=arena(4);s.cast(2);advance(s,.4);const before=e.soulMarks.length,negative=s.hasNegative(e);s.cleanse(e);const after=e.soulMarks?.length;e.immuneUntil=s.time+6;h.castUntil=0;const p=s.players[h.playerId];p.cd[2]=0;s.cast(2);advance(s,.4);const during=e.soulMarks?.length;out.observations.push({name:'soulmark-negative-policy',before,negative,after,during});assert.equal(after,0);assert.equal(during,0);return {before,negative,after,during};});
check('target death before non-AOE projectile impact safely misses without retarget',()=>{const {s,h,e}=arena(2);s.cast(0);advance(s,.4);s.damage(null,e,1e9);advance(s,2);assert.equal(s.projectiles.length,0);assert.ok(s.units.every(u=>[u.hp,u.x,u.y].every(Number.isFinite)));return {casts:s.metrics.casts};});
check('ordinary attack waits in range during cooldown, then attacks, without movement',()=>{const {s,h,e}=arena(0);e.y=1;h.targetId=e.id;h.speed=2;h.cd=.5;const hp=e.hp;advance(s,.4);assert.equal(e.hp,hp);assert.equal(h.y,0);advance(s,.15);assert.ok(Math.abs(hp-e.hp-h.attack)<1e-6);assert.equal(h.y,0);return {damage:hp-e.hp,cd:h.cd};});
check('rune channel blocks real chase and basic attack; interruption resumes both',()=>{const {s,h,e}=arena(2);e.y=11;h.speed=2;h.cd=0;h.targetId=e.id;assert.ok(s.cast(2));advance(s,1.2);assert.equal(h.y,0);assert.equal(h.lastAttackAt,undefined);assert.equal(s.castPlan(0).code,'channel');s.stun(h,e,.1);advance(s,.6);assert.ok(h.y>0);assert.ok(h.lastAttackAt>s.time-.6);return {resumedY:h.y,lastAttackAt:h.lastAttackAt,time:s.time};});
check('ordinary same-category tie breaks by ID and stale dead target is replaced',()=>{const {s,h,e,make}=arena(0);const e2=make(3,0,-3).h;e2.hp=1e7;h.targetId=null;assert.equal(s.choose(h).id,Math.min(e.id,e2.id));h.targetId=e.id;s.damage(null,e,1e9);assert.equal(s.choose(h).id,e2.id);return {old:e.id,next:e2.id};});
check('defense boundary stops advancing and still finds later enemy',()=>{const {s,h,e}=arena(3);s.units=s.units.filter(u=>u.side===1);h.y=s.config.world.defenseLimitY+.1;h.speed=2;advance(s,1);assert.equal(h.y,s.config.world.defenseLimitY);const target=s.spawn(0,'melee',0,1,0);Object.assign(target,{x:0,y:h.y+1,speed:0,cd:1e9});advance(s,.1);assert.equal(h.targetId,target.id);return {y:h.y,targetId:h.targetId};});
check('adjusted wave sizes stay independent of player count',()=>{const s=new Simulation();s.player.retired=true;s.units=[];s.config.world.attackWaveSize=7;s.config.world.defenseWaveSize=3;for(let i=0;i<20;i++)s.makePlayer(i%2,false);s.spawnWave();const counts=[s.units.filter(u=>u.side===0).length,s.units.filter(u=>u.side===1).length];assert.deepEqual(counts,[7,3]);return {players:s.players.length,counts};});
check('rune navigation follows current general hero>minion>tower rule; building bonus only basic',()=>{const {s,h,e}=arena(2);const t=s.towers[0];Object.assign(t,{x:0,y:1});h.targetId=null;assert.equal(s.choose(h).id,e.id);h.targetId=t.id;assert.equal(s.choose(h).id,t.id);const before=t.hp;s.damage(h,t,100,true);const basic=before-t.hp;assert.equal(basic,250);return {firstTarget:e.id,retainedTower:t.id,basicDamage:basic,buildingBonus:h.buildingBonus};});
for(const base of ['http://127.0.0.1:5183','http://192.168.36.82:5183']){const health=await(await fetch(base+'/api/health')).json(),html=await(await fetch(base+'/?v=skill5-20261024')).text();const match=[...html.matchAll(/(?:src|href)="(\/assets\/[^\"]+)"/g)].map(x=>x[1]);const assets=[];for(const url of match){const bytes=Buffer.from(await(await fetch(base+url)).arrayBuffer()),local=fs.readFileSync('dist'+url),hash=b=>crypto.createHash('sha256').update(b).digest('hex');assets.push({url,servedSha256:hash(bytes),localSha256:hash(local),matchesLocal:bytes.equals(local)});}out.observations.push({name:'production-read-only',base,health,title:html.match(/<title>(.*?)<\/title>/)?.[1],assets});}
const sources=[];for(const folder of ['client/src','shared','server'])for(const f of fs.readdirSync(folder))if(/\.(js|mjs|css)$/.test(f)){const file=folder+'/'+f;sources.push({file,sha256:crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex')});}for(const file of ['server/index.mjs','shared/default-config.json','README.md','规则与配置说明.md','测试说明.md'])sources.push({file,sha256:crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex')});out.sources=sources;
fs.writeFileSync(`${dir}/edge-audit.json`,JSON.stringify(out,null,2));console.log(JSON.stringify({passes:out.checks.filter(x=>x.status==='PASS').length,failures:out.checks.filter(x=>x.status==='FAIL'),observations:out.observations.filter(x=>x.name!=='rune-slow-timeline')},null,2));
